    # on right, then paint each matching zero-pattern in the frame.
    h, w = len(grid), len(grid[0])
    leftw = 5 if w >= 10 else w//2
    # collect nonzero colored object shapes from right half, ignoring background
    objects = {}
    for r in range(h):
        for c in range(leftw+1, w):
            col = grid[r][c]
            if col and col != grid[0][0]:
                cells=[]
                stack=[(r,c)]; seen={(r,c)}
                while stack:
                    y,x=stack.pop(); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        p=(y+dy,x+dx)
                        if 0<=p[0]<h and leftw<p[1]<w and p not in seen and grid[p[0]][p[1]]==col:
                            seen.add(p); stack.append(p)
                minr=min(y for y,x in cells); minc=min(x for y,x in cells)
